excels.excel:

EXPORT WITH SHEET="销售团队业绩排行榜", HEADER=true,
    MAPPING={"a":"排名","b":"销售员","c":"所属区域","d":"销售目标","e":"实际业绩","f":"完成率","g":"业绩等级"},
    FORMAT={"d":"#,##0.00","e":"#,##0.00","f":"0.00%"},
    FORMULAS={
        F2:'E2/D2',F3:'E3/D3',F4:'E4/D4',F5:'E5/D5',F6:'E6/D6',
        D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',F7:'E7/D7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F6:{color:red,bold:true}
    }
